const cfg = $('Config').first().json;
const override = String(cfg.batch_test_job_id || '').trim();
const items = ($json.items || []).slice();
items.sort((a, b) => (b.creation_timestamp || 0) - (a.creation_timestamp || 0));
let batch, source;
if (override) {
  batch = items.find(b => b.test_case_batch_job_id === override) || { test_case_batch_job_id: override };
  source = 'override';
} else {
  batch = items.length ? items[0] : null;
  source = items.length ? 'latest' : 'none';
}
const batchId = batch ? batch.test_case_batch_job_id : '';
if (!batchId) { throw new Error('No batch_test_job_id found. Run a batch test first or set batch_test_job_id in Config.'); }
return [{ json: {
  batch_test_job_id: batchId,
  source: source,
  batch_status: batch.status || '',
  pass_count: batch.pass_count != null ? batch.pass_count : null,
  fail_count: batch.fail_count != null ? batch.fail_count : null,
  error_count: batch.error_count != null ? batch.error_count : null,
  total_count: batch.total_count != null ? batch.total_count : null,
  creation_timestamp: batch.creation_timestamp || null
} }];

const batch = $('Pick Batch').first().json;
const flattenTranscript = (ts) => {
  if (!ts) return '';
  if (typeof ts === 'string') return ts;
  const arr = Array.isArray(ts) ? ts
    : Array.isArray(ts.transcript) ? ts.transcript
    : Array.isArray(ts.transcript_object) ? ts.transcript_object
    : Array.isArray(ts.utterances) ? ts.utterances
    : null;
  if (arr) return arr.filter(u => u && u.content).map(u => (u.role || u.speaker || '?') + ': ' + u.content).join(String.fromCharCode(10));
  if (typeof ts.transcript === 'string') return ts.transcript;
  return JSON.stringify(ts);
};
const items = $json.items || [];
return items.map(tr => {
  const snap = tr.test_case_definition_snapshot || {};
  return { json: {
    batch_test_job_id: batch.batch_test_job_id || '',
    batch_status: batch.batch_status || '',
    batch_pass: batch.pass_count,
    batch_fail: batch.fail_count,
    batch_error: batch.error_count,
    batch_total: batch.total_count,
    test_name: snap.name || '',
    status: tr.status || '',
    result_explanation: tr.result_explanation || '',
    transcript: flattenTranscript(tr.transcript_snapshot),
    test_case_definition_id: tr.test_case_definition_id || '',
    test_case_job_id: tr.test_case_job_id || '',
    metrics: snap.metrics || [],
    dynamic_variables: snap.dynamic_variables || {}
  } };
});
